      offset     = ru32(base + 16),
      n_elements = ru32(base + 20),
      shape      = { ru16(base + 24), ru16(base + 26), ru16(base + 28) },
      ndim       = ru8(base + 30),
    }
  end

  local sbase = 65 + hdr.n_tensors * 32
  local scales = {}
  for i = 1, hdr.n_tensors do
    scales[i] = rf32(sbase + (i - 1) * 4)
  end

  local data_start_0 = 64 + hdr.n_tensors * 32 + hdr.n_tensors * 4
  data_start_0 = data_start_0 + (64 - data_start_0 % 64) % 64
  local data_start = data_start_0 + 1

  local total = 0
  for i = 1, hdr.n_tensors do
    local e = tensors[i].offset + tensors[i].n_elements
    if e > total then total = e end
  end

  local data = {}
  for i = 1, hdr.n_tensors do
    local t = tensors[i]
    local off, ne, s = t.offset, t.n_elements, scales[i]
    local src = data_start + off
    for j = 1, ne do
      local b = mb[src + j - 1]
      if b >= 128 then b = b - 256 end
      data[off + j] = b * s
    end
  end

  return hdr, tensors, data, total
end

-- ---------- 张量查找 ----------
local function find_tensor(tensors, n, name)
  for i = 1, n do
    if tensors[i].name == name then return i end
  end
  return nil
end

-- ---------- 全局状态 ----------
local HDR, TENSORS, DATA, TOTAL
local NL, D, H, DH, FF, VOCAB_SZ, MS
local OFF_EMB, OFF_NF
local OFF_WQ, OFF_WK, OFF_WV, OFF_WO
local OFF_W1, OFF_W2, OFF_N1, OFF_N2
local INV_SQRT_DH

local g_ok = false
local g_err = ""

local function load_model()
  local ok, a, b, c, d = pcall(parse_model)
  if not ok then
    g_err = tostring(a)
    return false
  end
  HDR, TENSORS, DATA, TOTAL = a, b, c, d

  NL = HDR.n_layers
  D  = HDR.d_model
  H  = HDR.n_heads
  DH = math.floor(D / H)
  FF = HDR.d_ff
  VOCAB_SZ = HDR.vocab_size
  MS = HDR.max_seq
  if MS > 256 then MS = 256 end
  INV_SQRT_DH = 1 / math.sqrt(DH)

  local function need(name)
    local i = find_tensor(TENSORS, HDR.n_tensors, name)
    if not i then error("缺少张量: " .. name) end
    return i
  end

  local id_emb = need("emb")
  local id_nf  = need("nf")
  OFF_EMB = TENSORS[id_emb].offset
  OFF_NF  = TENSORS[id_nf].offset

  OFF_WQ, OFF_WK, OFF_WV, OFF_WO = {}, {}, {}, {}
  OFF_W1, OFF_W2, OFF_N1, OFF_N2 = {}, {}, {}, {}
  for L = 0, NL - 1 do
    OFF_WQ[L] = TENSORS[need("L" .. L .. ".wq")].offset
    OFF_WK[L] = TENSORS[need("L" .. L .. ".wk")].offset
    OFF_WV[L] = TENSORS[need("L" .. L .. ".wv")].offset
    OFF_WO[L] = TENSORS[need("L" .. L .. ".wo")].offset
    OFF_N1[L] = TENSORS[need("L" .. L .. ".n1")].offset
    OFF_W1[L] = TENSORS[need("L" .. L .. ".w1")].offset
    OFF_W2[L] = TENSORS[need("L" .. L .. ".w2")].offset
    OFF_N2[L] = TENSORS[need("L" .. L .. ".n2")].offset
  end

  return true
end

-- ---------- RoPE 预计算 ----------
local rope_cos, rope_sin

local function rope_init(d_head, max_seq, base)
  local half = math.floor(d_head / 2)
  rope_cos = {}
  rope_sin = {}
  for p = 0, max_seq - 1 do
    for i = 1, half do
      local theta = base ^ (-2.0 * (i - 1) / d_head)
      local a = p * theta
      rope_cos[p * half + i] = math.cos(a)
      rope_sin[p * half + i] = math.sin(a)
    end
  end
end

local function rope_apply(vec, base, pos, d_head)
  local half = math.floor(d_head / 2)
  local co = pos * half
  for i = 1, half do
    local c = rope_cos[co + i]
    local s = rope_sin[co + i]
    local i1 = base + i - 1
    local i2 = i1 + half
    local x1 = vec[i1]
    local x2 = vec[i2]
    vec[i1] = x1 * c - x2 * s
    vec[i2] = x1 * s + x2 * c
  end
end

-- ---------- 工作缓冲区 ----------
local x, xn, q, k, v, ao, proj, ff1, ff2, logits
local scores
local kv_k, kv_v

local function alloc_bufs()
  x, xn, q, k, v, ao, proj, ff2 = {}, {}, {}, {}, {}, {}, {}, {}
  ff1, logits, scores = {}, {}, {}

  for i = 1, D do
    x[i] = 0; xn[i] = 0; q[i] = 0; k[i] = 0; v[i] = 0
    ao[i] = 0; proj[i] = 0; ff2[i] = 0
  end
  for i = 1, FF do ff1[i] = 0 end
  for i = 1, VOCAB_SZ do logits[i] = 0 end
  for i = 1, MS do scores[i] = 0 end

  local kvn = NL * MS * D
  kv_k, kv_v = {}, {}
  for i = 1, kvn do
    kv_k[i] = 0
    kv_v[i] = 0
  end
end

-- ---------- 基础算子 ----------
local function rmsnorm(vv, goff)
  local ss = 0
  for i = 1, D do
    local t = vv[i]
    ss = ss + t * t
  end
  local inv = 1 / math.sqrt(ss / D + 1e-6)
  for i = 1, D do
    vv[i] = vv[i] * inv * DATA[goff + i]
  end
end

local function matvec(W, woff, o_dim, i_dim, xv, yv)
  for o = 1, o_dim do
    local rb = woff + (o - 1) * i_dim
    local acc = 0
    for i = 1, i_dim do
      acc = acc + W[rb + i] * xv[i]
    end
    yv[o] = acc
  end
end

-- ---------- 单步前向 ----------
local function forward_one(token, pos)
  local d  = D
  local h  = H
  local dh = DH
  local ff = FF
  local nl = NL
  local V  = VOCAB_SZ

  local b = OFF_EMB + token * d
  for i = 1, d do x[i] = DATA[b + i] end

  for L = 0, nl - 1 do
    for i = 1, d do xn[i] = x[i] end
    rmsnorm(xn, OFF_N1[L])

    matvec(DATA, OFF_WQ[L], d, d, xn, q)
    matvec(DATA, OFF_WK[L], d, d, xn, k)
    matvec(DATA, OFF_WV[L], d, d, xn, v)

    for hh = 0, h - 1 do
      rope_apply(q, hh * dh + 1, pos, dh)
      rope_apply(k, hh * dh + 1, pos, dh)
    end

    local cb = (L * MS + pos) * d
    for i = 1, d do
      kv_k[cb + i] = k[i]
      kv_v[cb + i] = v[i]
    end

    local inv_sqrt_dh = INV_SQRT_DH
    for hh = 0, h - 1 do
      local qb = hh * dh
      local ab = hh * dh
      local maxs = -1e30
      for t = 0, pos do
        local kb = (L * MS + t) * d + hh * dh
        local s = 0
        for i = 1, dh do
          s = s + q[qb + i] * kv_k[kb + i]
        end
        s = s * inv_sqrt_dh
        scores[t + 1] = s
        if s > maxs then maxs = s end
      end
      local sum = 0
      for t = 1, pos + 1 do
        local e = math.exp(scores[t] - maxs)
        scores[t] = e
        sum = sum + e
      end
      local inv_sum = 1 / sum
      for i = 1, dh do ao[ab + i] = 0 end
      for t = 0, pos do
        local w = scores[t + 1] * inv_sum
        local vb = (L * MS + t) * d + hh * dh
        for i = 1, dh do
          ao[ab + i] = ao[ab + i] + w * kv_v[vb + i]
        end
      end
    end

    matvec(DATA, OFF_WO[L], d, d, ao, proj)
    for i = 1, d do x[i] = x[i] + proj[i] end

    for i = 1, d do xn[i] = x[i] end
    rmsnorm(xn, OFF_N2[L])
    matvec(DATA, OFF_W1[L], ff, d, xn, ff1)
    for i = 1, ff do
      local xx = ff1[i]
      ff1[i] = 0.5 * xx * (1 + math.tanh(0.7978845608 * (xx + 0.044715 * xx * xx * xx)))
    end
    matvec(DATA, OFF_W2[L], d, ff, ff1, ff2)
    for i = 1, d do x[i] = x[i] + ff2[i] end
  end

  rmsnorm(x, OFF_NF)

  for vv = 1, V do
    local eo = OFF_EMB + (vv - 1) * d
    local s = 0
    for i = 1, d do
      s = s + DATA[eo + i] * x[i]
    end
    logits[vv] = s
  end
end

-- ---------- 采样 ----------
local function sample_token(n, history, hist_len, rep_penalty)
  local adjusted = {}
  for i = 1, n do adjusted[i] = logits[i] end

  if hist_len >= 3 then
    local b0 = history[hist_len - 2]
    local b1 = history[hist_len - 1]
    local b2 = history[hist_len]
    local repeated = false
    for i = 1, hist_len - 3 do
      if history[i] == b0 and history[i + 1] == b1 and history[i + 2] == b2 then
        repeated = true
        break
      end
    end
    if repeated then
      adjusted[b0 + 1] = adjusted[b0 + 1] - rep_penalty
      adjusted[b1 + 1] = adjusted[b1 + 1] - rep_penalty
      adjusted[b2 + 1] = adjusted[b2 + 1] - rep_penalty
    end
  end

  local best = 1
  local bestv = adjusted[1]
  for i = 2, n do
    if adjusted[i] > bestv then
      bestv = adjusted[i]
      best = i
    end
  end
  return best - 1
end

-- ---------- 生成（协程内运行） ----------
local function generate(prompt, plen, max_new, out)
  for i = 1, NL * MS * D do
    kv_k[i] = 0
    kv_v[i] = 0
  end

  local pos = 0
  for i = 1, plen do
    if pos >= MS then break end
    forward_one(prompt[i], pos)
    pos = pos + 1
  end

  local history = {}
  local hist_len = 0
  local out_len = 0

  for s = 1, max_new do
    if pos >= MS then break end
    local nxt = sample_token(VOCAB_SZ, history, hist_len, 5.0)
    out_len = out_len + 1
    out[out_len] = nxt
    hist_len = hist_len + 1
    history[hist_len] = nxt
    if nxt == 10 then break end
    forward_one(nxt, pos)
    pos = pos + 1
    coroutine.yield()
  end

  return out_len
end

-- ============================================================
--  界面状态
-- ============================================================
local ctx = {}
local input_str = ""
local scroll = 0
local render_lines = {}
local render_dirty = true
local gen_co = nil
local gen_out = nil
local busy = false
local lineH = 14
local visLines = 10

-- UTF-8 输入累加缓冲
local input_pending = {}
local pending_need  = 0

-- ---------- UTF-8 工具 ----------
local function utf8_need_bytes(c)
  if c < 0x80 then return 1
  elseif c < 0xC0 then return 1
  elseif c < 0xE0 then return 2
  elseif c < 0xF0 then return 3
  else return 4 end
end

local function utf8_chars(s)
  local t = {}
  local i, n = 1, #s
  while i <= n do
    local c = string.byte(s, i)
    local len = 1
    if c < 0x80 then len = 1
    elseif c < 0xE0 then len = 2
    elseif c < 0xF0 then len = 3
    else len = 4 end
    t[#t + 1] = string.sub(s, i, i + len - 1)
    i = i + len
  end
  return t
end

local function utf8_remove_last(s)
  local n = #s
  if n == 0 then return s end
  local i = n
  while i >= 1 do
    local b = string.byte(s, i)
    if b >= 0x80 and b < 0xC0 then
      i = i - 1
    else
      break
    end
  end
  return string.sub(s, 1, i - 1)
end

local function str_to_bytes(s)
  local t = {}
  for i = 1, #s do t[i] = string.byte(s, i) end
  return t
end

local function bytes_to_str(t, n)
  local c = {}
  for i = 1, n do c[i] = string.char(t[i]) end
  return table.concat(c)
end

local function split_newlines(s)
  local parts = {}
  local start = 1
  while true do
    local i = string.find(s, "\n", start, true)
    if not i then
      parts[#parts + 1] = string.sub(s, start)
      break
    end
    parts[#parts + 1] = string.sub(s, start, i - 1)
    start = i + 1
  end
  return parts
end

-- ---------- 安全设置字体 ----------
local function safe_setFont(gc)
  local ok = pcall(gc.setFont, gc, "sansserif", "r", 9)
  if not ok then
    pcall(gc.setFont, gc, "serif", "r", 9)
  end
end

-- ---------- 换行 ----------
local function wrap_msg(gc, prefix, text, maxw)
  local pw = gc:getStringWidth(prefix)
  local sw = gc:getStringWidth(" ")
  local nspace = 0
  if sw > 0 then nspace = math.floor(pw / sw + 0.5) end
  local indent = string.rep(" ", nspace)
  local iw = gc:getStringWidth(indent)

  local out = {}
  local paras = split_newlines(text)
  for pi = 1, #paras do
    local chars = utf8_chars(paras[pi])
    local cur = (pi == 1) and prefix or indent
    local cw = (pi == 1) and pw or iw
    if #chars == 0 then
      out[#out + 1] = cur
    else
      for i = 1, #chars do
        local w = gc:getStringWidth(chars[i])
        if cw + w > maxw and #cur > 0 then
          out[#out + 1] = cur
          cur = indent
          cw = iw
        end
        cur = cur .. chars[i]
        cw = cw + w
      end
      out[#out + 1] = cur
    end
  end
  if #out == 0 then out[1] = prefix end
  return out
end

local function rebuild_lines(gc, maxw)
  safe_setFont(gc)

  render_lines = {}
  if #ctx == 0 then
    render_lines[1] = { text = "输入内容后按 Enter 发送。", role = "info" }
    return
  end
  for ci = 1, #ctx do
    local e = ctx[ci]
    local prefix
    if e.role == "user" then
      prefix = "> "
    else
      prefix = "AI: "
    end
    local wrapped = wrap_msg(gc, prefix, e.text, maxw)
    for wi = 1, #wrapped do
      render_lines[#render_lines + 1] = { text = wrapped[wi], role = e.role }
    end
  end
end

-- ---------- 生成入口 ----------
local function start_generate(user_text)
  local prompt = {}
  prompt[1] = 0x01
  local bs = str_to_bytes(user_text)
  for i = 1, #bs do prompt[#prompt + 1] = bs[i] end
  prompt[#prompt + 1] = 0x0A
  prompt[#prompt + 1] = 0x02

  gen_out = {}
  gen_co = coroutine.create(function()
    return generate(prompt, #prompt, 120, gen_out)
  end)
  busy = true
  timer.start(0.05)
end

-- ============================================================
--  顶层初始化
-- ============================================================
do
  local ok = load_model()
  if not ok then
    ctx[1] = { role = "ai", text = "模型加载失败：" .. g_err }
    render_dirty = true
  else
    rope_init(DH, MS, 10000.0)
    alloc_bufs()
    g_ok = true
  end
end

-- 菜单
toolpalette.register({
  {
    "对话",
    { "清空上下文", function()
        ctx = {}
        scroll = 0
        render_dirty = true
        platform.window:invalidate()
      end
    },
    { "粘贴剪贴板", function()
        local t = clipboard.getText()
        if t and #t > 0 then
          -- 把换行、Tab 等控制字符替换成空格，避免输入框显示异常
          t = t:gsub("[\r\n\t]", " ")
          input_str = input_str .. t
          render_dirty = true
          platform.window:invalidate()
        end
      end
    }
  }
})

-- ============================================================
--  事件
-- ============================================================
function on.resize(w, h)
  render_dirty = true
  platform.window:invalidate()
end

function on.activate()
  platform.window:invalidate()
end

function on.paint(gc)
  local W = platform.window:width()
  local H = platform.window:height()

  gc:setColorRGB(0xFFFFFF)
  gc:fillRect(0, 0, W, H)

  safe_setFont(gc)

  lineH = gc:getStringHeight("Ag")
  if not lineH or lineH < 10 then lineH = 12 end

  local inpH = lineH + 6
  local histH = H - inpH - 4
  visLines = math.floor(histH / lineH)
  if visLines < 1 then visLines = 1 end

  if render_dirty then
    rebuild_lines(gc, W - 8)
    render_dirty = false
  end

  gc:setColorRGB(0xCC0000)
  gc:drawString("g_ok=" .. tostring(g_ok), 4, H - inpH - 18, "top")
  if g_err ~= "" then
    gc:drawString("err=" .. string.sub(g_err, 1, 40), 60, H - inpH - 18, "top")
  end

  local total = #render_lines
  local maxScroll = total - visLines
  if maxScroll < 0 then maxScroll = 0 end
  if scroll > maxScroll then scroll = maxScroll end
  if scroll < 0 then scroll = 0 end

  local startIdx = total - visLines - scroll + 1
  if startIdx < 1 then startIdx = 1 end
  local endIdx = startIdx + visLines - 1
  if endIdx > total then endIdx = total end

  local y = 2
  for i = startIdx, endIdx do
    local ln = render_lines[i]
    if ln.role == "user" then
      gc:setColorRGB(0x1A3F8C)
    elseif ln.role == "ai" then
      gc:setColorRGB(0x146B3A)
    else
      gc:setColorRGB(0x666666)
    end
    gc:drawString(ln.text, 4, y, "top")
    y = y + lineH
  end

  gc:setColorRGB(0x202020)
  gc:fillRect(0, H - inpH, W, inpH)

  gc:setColorRGB(0xFFFFFF)
  local caret = busy and " ..." or "_"
  gc:drawString("> " .. input_str .. caret, 4, H - inpH + 3, "top")
end

function on.charIn(ch)
  local c = string.byte(ch, 1)
  if not c then return end

  if pending_need == 0 then
    local need = utf8_need_bytes(c)
    if need == 1 then
      input_str = input_str .. ch
      platform.window:invalidate()
      return
    end
    input_pending = { c }
    pending_need = need - 1
  else
    input_pending[#input_pending + 1] = c
    pending_need = pending_need - 1
    if pending_need == 0 then
      local t = {}
      for i = 1, #input_pending do t[i] = string.char(input_pending[i]) end
      input_str = input_str .. table.concat(t)
      input_pending = {}
    end
  end
  platform.window:invalidate()
end

function on.backspaceKey()
  if pending_need > 0 then
    input_pending = {}
    pending_need = 0
  else
    input_str = utf8_remove_last(input_str)
  end
  platform.window:invalidate()
end

function on.escapeKey()
  input_str = ""
  input_pending = {}
  pending_need = 0
  platform.window:invalidate()
end

function on.enterKey()
  if busy then return end
  if not g_ok then
    ctx[#ctx + 1] = { role = "ai", text = "模型未加载成功，无法生成。" }
    render_dirty = true
    platform.window:invalidate()
    return
  end
  if #input_str == 0 then return end

  ctx[#ctx + 1] = { role = "user", text = input_str }
  local u = input_str
  input_str = ""
  input_pending = {}
  pending_need = 0
  scroll = 0
  render_dirty = true
  platform.window:invalidate()

  start_generate(u)
end

function on.arrowUp()
  scroll = scroll + 3
  platform.window:invalidate()
end

function on.arrowDown()
  scroll = scroll - 3
  if scroll < 0 then scroll = 0 end
  platform.window:invalidate()
end

function on.timer()
  if not gen_co then
    timer.stop()
    return
  end

  local ok, n = coroutine.resume(gen_co)

  if coroutine.status(gen_co) == "dead" then
    gen_co = nil
    timer.stop()
    busy = false
    if ok and n and n > 0 then
      ctx[#ctx + 1] = { role = "ai", text = bytes_to_str(gen_out, n) }
    else
      ctx[#ctx + 1] = { role = "ai", text = "(无输出)" }
    end
    scroll = 0
    render_dirty = true
  end

  platform.window:invalidate()
end